f_Quality_fit <- function(df, group){
  df_res <- df |> 
    group_by(across(all_of(group))) |> 
    summarise(
        Fold_mean = mean(Fold, na.rm = TRUE),
        Bias = mean(Residuals, na.rm = TRUE),
        Mean_relative_error = mean(Relative_error, na.rm = TRUE),
        Mean_LogPredObs = mean(LogPredObs, na.rm = TRUE),
        .groups = "drop"
      ) |> 
    ungroup() |> 
    mutate(Mean_PredObs = exp(Mean_LogPredObs))
}

f_Experiment_Conditions <- function(df){
  df_res <- df |> 
  mutate(
    Status = case_when(
      ID_experiment == "Bart2019_XP1_1" ~ "J",
      ID_experiment == "Bart2019_XP1_2" & Time <= 84 ~ "J",
      ID_experiment == "Bart2019_XP1_2" & Time > 84 ~ "A",
      ID_experiment == "Bart2019_XP3" ~ "J",
      ID_experiment == "Bart2019_XP4_1" ~ "J",
      ID_experiment == "Bart2019_XP4_2" & Time <= 112 ~ "J",
      ID_experiment == "Bart2019_XP4_2" & Time > 112 ~ "A",
      ID_experiment == "Bart2019_XP5" ~ "J",
      ID_experiment == "Bart2020" ~ "J",
      ID_experiment == "Gollot2026_dens_D1" ~ "J",
      ID_experiment == "Gollot2026_dens_D2" & Time <= 70 ~ "J",
      ID_experiment == "Gollot2026_dens_D2" & Time > 70 ~ "A",
      ID_experiment == "Gollot2026_dens_D2b" & Time <= 70 ~ "J",
      ID_experiment == "Gollot2026_dens_D2b" & Time > 70 ~ "A",
      ID_experiment == "Gollot2026_dens_D5" & Time <= 70 ~ "J",
      ID_experiment == "Gollot2026_dens_D5" & Time > 70 ~ "A",
      ID_experiment == "Gollot2026_dens_D7" ~ "J"
    )
  ) |> 
  mutate(Status = factor(Status, levels = c("J", "A")))

  return(df_res)
}

df_predobs_Weight_D_CWKe_Fit <- f_Experiment_Conditions(df_predobs_Weight_D_CWKe_plot)

df_predobs_Weight_D_CWKe_Fit <- df_predobs_Weight_D_CWKe_Fit |> 
  mutate(
    Fold = ifelse(predict.endpoint > Weight_obs, predict.endpoint/Weight_obs, Weight_obs/predict.endpoint),
    Residuals = predict.endpoint-Weight_obs,
    Relative_error = (predict.endpoint-Weight_obs)/Weight_obs,
    LogPredObs = log(predict.endpoint/Weight_obs)
    )

df_fold_D_Weight_Dens <- f_Quality_fit(df_predobs_Weight_D_CWKe_Fit, "Density_env")
df_fold_D_Weight_Food <- f_Quality_fit(df_predobs_Weight_D_CWKe_Fit, "Food_env")
df_fold_D_Weight_Temp <- f_Quality_fit(df_predobs_Weight_D_CWKe_Fit, "T_env")

