```{.r .cell-code}
path_fig <- here::here("fig/AS")
path_AS <- here::here("mod/X_AS")

seed       <- 361224
Sobol_type <- "Jansen"
Nb_sim     <- 30000 # (p + 2) * Nb_sim simulations 30000
CV         <- 0.1 # 1000
processors <- 2
Nboot      <- 1000  # nb replicat

l_params_median <- c(
  # Environment
  muOM = 13000, rOM_ClxHorse = 0.0294325,
  # Energy assimilation
  Fm = 3.87576, kapX = 0.258, K = 0.0546564, pAm = 259.953, v = 0.230918,
  kapJ  = 0.983041, kapA = 0.707631, 
  tau = 11.9528,
  # Maintenance and growth
  r_pAm_pM = 0.70081, Eg = 4183, dv = 1.2135, de = 1.130890e-09,
  # Maturity
  kJ = 0.002793, Ehb = 0.5, Ehp = 73.1002,
  # Reproduction
  E_coc = 57.8342, kapR = 0.475,
  # Metabolic response to T
  TAH = 28750, TH = 293.2, TA = 7976, Tref = 293.15
)

# With temperature parameters

Sobol_design_T <- f_AS_Sobol_design(Sobol_type = Sobol_type, seed = seed, Nb_sim = Nb_sim, CV = CV, Processors = Processors, Nboot = Nboot, l_params_median = l_params_median, Temperature_bol = TRUE)
l_Sobol_param_T <- Sobol_design_T$Sobol_param
Sobol_info_T <- Sobol_design_T$Sobol

file_rds_AS_T <- file.path(path_AS, paste0("df_Sobol_param_T.rds"))
file_txt_AS_T <- here::here(paste0("mod/X_AS/Param_sobol_", Sobol_type, "_T.txt"))

if (file.exists(file_rds_AS_T)) {
  df_Sobol_param_T <- readRDS(file_rds_AS_T)
} else {

  library(data.table)

  df_Sobol_param_T <- rbindlist(
    l_Sobol_param_T,
    use.names = TRUE,
    fill = FALSE
  )

  df_Sobol_param_T <- cbind(id = seq_len(nrow(df_Sobol_param_T)), df_Sobol_param_T)

  saveRDS(df_Sobol_param_T, file_rds_AS_T)

  fwrite(
    df_Sobol_param_T,
    file = file_txt_AS_T,
    sep = "\t",
    quote = FALSE
  )

}

